(7313620, 1141197, 177553, '<td valign="top">Good idea. My only issue is that the shot appears to be in focus front to back. It kind of flattens the image.  Maybe a little bokeh in the background could have helped this. JMO :)</td>', 'Good idea. My only issue is that the shot appears to be in focus front to back. It kind of flattens the image.  Maybe a little bokeh in the background could have helped this. JMO :)', '2015-02-07 12:01:11.000000', NULL, 1),
(7313626, 1141184, 177553, '<td valign="top">Difficult shot in my opinion. Good idea, but it takes quite a bit of searching to find the tradesman initially.  I''m drawn to the railing and bell more than anything.</td>', 'Difficult shot in my opinion. Good idea, but it takes quite a bit of searching to find the tradesman initially.  I''m drawn to the railing and bell more than anything.', '2015-02-07 12:28:30.000000', NULL, 1),
(7313627, 1141011, 177553, '<td valign="top">Good idea. I like that you caught the smoke from the grill and that her eye is in focus. Gotta dock a point for no meat on the grill though... :)</td>', 'Good idea. I like that you caught the smoke from the grill and that her eye is in focus. Gotta dock a point for no meat on the grill though... :)', '2015-02-07 12:30:33.000000', NULL, 1),
(7313629, 1141210, 177553, '<td valign="top">Good concept and idea. I would have liked to see something painted on the canvas and maybe continued out to the blue swirls. Good job.</td>', 'Good concept and idea. I would have liked to see something painted on the canvas and maybe continued out to the blue swirls. Good job.', '2015-02-07 12:32:51.000000', NULL, 1),
(7313630, 1140591, 177553, '<td valign="top">Good job, I like the grainy look to the shot and the BW helps here. Reminds me of an older time.</td>', 'Good job, I like the grainy look to the shot and the BW helps here. Reminds me of an older time.', '2015-02-07 12:33:49.000000', NULL, 1),
